messages.content:
Game edukasi "Input Output Dash" siap dibangun: Endless Runner bertema Neon di mana pemain mengambil perangkat sesuai target kategori Input atau Output. Asumsi penting: rintangan berupa kabel dan perangkat rusak, dengan item belajar memakai 8 perangkat dari PRD.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "input-output-dash", title: "Input Output Dash", seed: "input-output-01",
  theme: { preset: "neon" },

  learning: {
    subject: "Teknologi Informasi",
    concept: "Perangkat input memasukkan data ke komputer, perangkat output menampilkan atau mengeluarkan hasil",
    objectives: ["Mengelompokkan perangkat komputer sebagai input atau output berdasarkan fungsinya"],
    misconceptions: ["Monitor dan printer dianggap perangkat input karena bisa disentuh dan dipegang"],
    mode: "category",
    categories: [
      { id: "input",  label: "Input",  color: "#22D3EE" },
      { id: "output", label: "Output", color: "#F472B6" }
    ],
    items: [
      { id: "keyboard",  label: "Keyboard",  category: "input",  explain: "Mengetik huruf dan angka agar masuk ke komputer." },
      { id: "mouse",     label: "Mouse",     category: "input",  explain: "Menggerakkan kursor dan memberi perintah klik ke komputer." },
      { id: "scanner",   label: "Scanner",   category: "input",  explain: "Memindai dokumen menjadi data digital masuk ke komputer." },
      { id: "mikrofon",  label: "Mikrofon",  category: "input",  explain: "Menangkap suara dan mengubahnya menjadi data untuk komputer." },
      { id: "monitor",   label: "Monitor",   category: "output", explain: "Menampilkan gambar dan teks hasil olahan komputer." },
      { id: "printer",   label: "Printer",   category: "output", explain: "Mencetak hasil olahan komputer ke kertas." },
      { id: "speaker",   label: "Speaker",   category: "output", explain: "Mengeluarkan suara dari komputer." },
      { id: "proyektor", label: "Proyektor", category: "output", explain: "Menampilkan gambar dari komputer ke layar besar." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "kabel",    w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "perangkat", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
